using Point=std::array<long double,3>;
struct Failure:std::runtime_error{int code;Failure(int c,const char* text):std::runtime_error(text),code(c){}};
void require(bool value,const char* text){if(!value)throw Failure(1,text);}
void message(char* out,uint64_t cap,const char* text){if(out&&cap){const auto n=std::min<uint64_t>(cap-1,std::strlen(text));std::memcpy(out,text,n);out[n]=0;}}
Point sub(const Point& a,const Point& b){return {a[0]-b[0],a[1]-b[1],a[2]-b[2]};}Point add(const Point& a,const Point& b){return {a[0]+b[0],a[1]+b[1],a[2]+b[2]};}Point mul(const Point& a,long double s){return {a[0]*s,a[1]*s,a[2]*s};}long double dot(const Point& a,const Point& b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}Point cross(const Point& a,const Point& b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}long double length(const Point& a){return std::sqrt(dot(a,a));}
double finite(long double value){if(!std::isfinite(value)||std::abs(value)>std::numeric_limits<double>::max())throw Failure(2,"Mesh intersection coordinate is not representable.");return static_cast<double>(value);}
struct Work{const penta_geometry_extra_host_v1& host;const penta_mesh_intersection_request_v1& q;std::atomic_uint64_t used{0},primitives{0};std::chrono::steady_clock::time_point start=std::chrono::steady_clock::now();void spend(uint64_t amount){if(host.cancelled(host.context))throw Failure(3,"Mesh intersection cancelled.");if(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()>q.max_seconds)throw Failure(7,"Mesh intersection wall-time allowance exceeded.");auto before=used.load();do{if(before>q.max_work||amount>q.max_work-before)throw Failure(7,"Mesh intersection work allowance exceeded.");}while(!used.compare_exchange_weak(before,before+amount));}};
struct Triangle{std::array<Point,3> point;Point low,high,center;std::array<uint64_t,3> vertices;};struct Box{Point low{},high{};uint64_t first=0,count=0;int left=-1,right=-1;};
bool overlap(const Point& a,const Point& b,const Point& c,const Point& d,long double tolerance){for(unsigned k=0;k<3;++k)if(a[k]>d[k]+tolerance||c[k]>b[k]+tolerance)return false;return true;}
class Tree{Work& work_;std::vector<Triangle> triangles_;std::vector<uint64_t> order_;std::vector<Box> boxes_;int build(uint64_t first,uint64_t last){work_.spend(6*(last-first));const auto id=static_cast<int>(boxes_.size());boxes_.push_back({});Box box;box.first=first;box.count=last-first;for(unsigned k=0;k<3;++k){box.low[k]=std::numeric_limits<long double>::infinity();box.high[k]=-box.low[k];for(auto at=first;at<last;++at){box.low[k]=std::min(box.low[k],triangles_[order_[at]].low[k]);box.high[k]=std::max(box.high[k],triangles_[order_[at]].high[k]);}}if(last-first>8){unsigned axis=0;for(unsigned k=1;k<3;++k)if(box.high[k]-box.low[k]>box.high[axis]-box.low[axis])axis=k;const auto middle=first+(last-first)/2;std::nth_element(order_.begin()+first,order_.begin()+middle,order_.begin()+last,[&](auto a,auto b){return triangles_[a].center[axis]<triangles_[b].center[axis]||(triangles_[a].center[axis]==triangles_[b].center[axis]&&a<b);});box.left=build(first,middle);box.right=build(middle,last);box.count=0;}boxes_[id]=box;return id;}
public:Tree(Work& work,const penta_surface_mesh_v1& mesh):work_(work){triangles_.reserve(mesh.triangles);for(uint64_t face=0;face<mesh.triangles;++face){work_.spend(100);Triangle t;for(unsigned j=0;j<3;++j){const auto v=mesh.faces[3*face+j];require(v>=1&&v<=mesh.vertices,"Mesh intersection face index is invalid.");t.vertices[j]=v-1;for(unsigned k=0;k<3;++k){const auto value=mesh.points[3*(v-1)+k];require(std::isfinite(value),"Mesh intersection vertices must be finite.");t.point[j][k]=value;}}const auto a=sub(t.point[1],t.point[0]),b=sub(t.point[2],t.point[0]);const auto scale=std::max(length(a),length(b));require(scale>0&&length(cross(mul(a,1/scale),mul(b,1/scale)))>1e-10L,"Mesh intersection triangles must be resolved and nondegenerate.");for(unsigned k=0;k<3;++k){t.low[k]=std::min({t.point[0][k],t.point[1][k],t.point[2][k]});t.high[k]=std::max({t.point[0][k],t.point[1][k],t.point[2][k]});t.center[k]=t.point[0][k]/3+t.point[1][k]/3+t.point[2][k]/3;}triangles_.push_back(t);}order_.resize(mesh.triangles);std::iota(order_.begin(),order_.end(),0);boxes_.reserve(2*mesh.triangles);build(0,mesh.triangles);}
const Triangle& triangle(uint64_t n)const{return triangles_[n];}std::vector<uint64_t> candidates(const Triangle& source){std::vector<uint64_t> result;std::vector<int> stack{0};while(!stack.empty()){work_.spend(6);const auto at=stack.back();stack.pop_back();const auto& box=boxes_[at];if(!overlap(source.low,source.high,box.low,box.high,work_.q.tolerance))continue;if(box.count)for(uint64_t j=box.first;j<box.first+box.count;++j){const auto face=order_[j];if(overlap(source.low,source.high,triangles_[face].low,triangles_[face].high,work_.q.tolerance))result.push_back(face);}else{stack.push_back(box.left);stack.push_back(box.right);}}std::sort(result.begin(),result.end());return result;}};
struct Primitive{std::array<Point,6> points{};unsigned count=0,dimension=0;bool coplanar=false;uint64_t first=0,second=0;};
void unique(std::vector<Point>& values,long double tolerance){std::vector<Point> result;for(const auto& p:values)if(std::none_of(result.begin(),result.end(),[&](const auto& x){return length(sub(p,x))<=tolerance;}))result.push_back(p);values=std::move(result);}
std::vector<Point> section(const std::array<Point,3>& points,const std::array<long double,3>& distance,long double tolerance){std::vector<Point> result;for(unsigned j=0;j<3;++j){const auto k=(j+1)%3;if(std::abs(distance[j])<=tolerance)result.push_back(points[j]);if((distance[j]>tolerance&&distance[k]<-tolerance)||(distance[j]<-tolerance&&distance[k]>tolerance)){const auto fraction=distance[j]/(distance[j]-distance[k]);result.push_back(add(points[j],mul(sub(points[k],points[j]),fraction)));}}unique(result,tolerance);return result;}
Primitive intersect(const Triangle& first,const Triangle& second,long double absoluteTolerance,Work& work){work.spend(1500);Primitive result;const auto origin=first.point[0];long double scale=0;for(const auto& p:first.point)scale=std::max(scale,length(sub(p,origin)));for(const auto& p:second.point)scale=std::max(scale,length(sub(p,origin)));require(scale>0,"Unresolved intersection coordinates.");std::array<Point,3> a,b;for(unsigned j=0;j<3;++j){a[j]=mul(sub(first.point[j],origin),1/scale);b[j]=mul(sub(second.point[j],origin),1/scale);}const auto tolerance=std::max(absoluteTolerance/scale,128*std::numeric_limits<long double>::epsilon());auto na=cross(sub(a[1],a[0]),sub(a[2],a[0])),nb=cross(sub(b[1],b[0]),sub(b[2],b[0]));na=mul(na,1/length(na));nb=mul(nb,1/length(nb));std::array<long double,3> da{},db{};for(unsigned j=0;j<3;++j){da[j]=dot(sub(a[j],b[0]),nb);db[j]=dot(sub(b[j],a[0]),na);}auto separated=[&](const auto& values){return *std::min_element(values.begin(),values.end())>tolerance||*std::max_element(values.begin(),values.end())<-tolerance;};if(separated(da)||separated(db))return result;const bool coplanar=std::all_of(da.begin(),da.end(),[&](auto v){return std::abs(v)<=tolerance;})&&std::all_of(db.begin(),db.end(),[&](auto v){return std::abs(v)<=tolerance;});std::vector<Point> points;
    if(coplanar){result.coplanar=true;unsigned drop=0;for(unsigned k=1;k<3;++k)if(std::abs(na[k])>std::abs(na[drop]))drop=k;const unsigned x=(drop+1)%3,y=(drop+2)%3;const auto orient=[&](const Point& p,const Point& q,const Point& r){return (q[x]-p[x])*(r[y]-p[y])-(q[y]-p[y])*(r[x]-p[x]);};const auto sign=orient(a[0],a[1],a[2])>0?1.L:-1.L;points.assign(b.begin(),b.end());for(unsigned edge=0;edge<3&&!points.empty();++edge){std::vector<Point> clipped;const auto& from=a[edge];const auto& to=a[(edge+1)%3];const auto edgeLength=std::hypot(to[x]-from[x],to[y]-from[y]);for(std::size_t j=0;j<points.size();++j){const auto& p=points[j];const auto& q=points[(j+1)%points.size()];const auto dp=sign*orient(from,to,p)/edgeLength,dq=sign*orient(from,to,q)/edgeLength;const bool insideP=dp>=-tolerance,insideQ=dq>=-tolerance;if(insideP)clipped.push_back(p);if(insideP!=insideQ){const auto fraction=std::clamp(dp/(dp-dq),0.L,1.L);clipped.push_back(add(p,mul(sub(q,p),fraction)));}}unique(clipped,tolerance);points=std::move(clipped);}unique(points,tolerance);if(points.size()>=3){long double area=0;for(std::size_t j=0;j<points.size();++j)area+=points[j][x]*points[(j+1)%points.size()][y]-points[j][y]*points[(j+1)%points.size()][x];if(std::abs(area)>tolerance*tolerance){result.dimension=2;if(area*sign<0)std::reverse(points.begin(),points.end());}else{std::pair<std::size_t,std::size_t> farthest{};long double maximum=-1;for(std::size_t i=0;i<points.size();++i)for(std::size_t j=i+1;j<points.size();++j){const auto delta=sub(points[i],points[j]);if(dot(delta,delta)>maximum){maximum=dot(delta,delta);farthest={i,j};}}points={points[farthest.first],points[farthest.second]};}}}
    else{auto line=cross(na,nb);const auto lineLength=length(line);if(lineLength<=128*std::numeric_limits<long double>::epsilon())return result;line=mul(line,1/lineLength);const auto sa=section(a,da,tolerance),sb=section(b,db,tolerance);if(sa.empty()||sb.empty())return result;auto interval=[&](const auto& list){std::pair<long double,long double> range{dot(list[0],line),dot(list[0],line)};for(const auto& p:list){const auto parameter=dot(p,line);range.first=std::min(range.first,parameter);range.second=std::max(range.second,parameter);}return range;};const auto ia=interval(sa),ib=interval(sb);const auto lower=std::max(ia.first,ib.first),upper=std::min(ia.second,ib.second);if(lower>upper+tolerance)return result;auto at=[&](long double t){return add(sa[0],mul(line,t-dot(sa[0],line)));};points.push_back(at((upper-lower)<=tolerance?(lower+upper)/2:lower));if(upper-lower>tolerance)points.push_back(at(upper));}
    unique(points,tolerance);require(points.size()<=6,"Resolved triangle overlap exceeded six vertices.");result.count=static_cast<unsigned>(points.size());if(result.dimension!=2)result.dimension=result.count>1?1:0;for(unsigned j=0;j<result.count;++j)result.points[j]=add(origin,mul(points[j],scale));return result;
}
std::array<long double,3> barycentric(const Triangle& triangle,const Point& point){const auto a=sub(triangle.point[1],triangle.point[0]),b=sub(triangle.point[2],triangle.point[0]),x=sub(point,triangle.point[0]);const auto scale=std::max(length(a),length(b));const auto u=mul(a,1/scale),v=mul(b,1/scale),w=mul(x,1/scale);const auto aa=dot(u,u),bb=dot(v,v),ab=dot(u,v),det=aa*bb-ab*ab;const auto first=(dot(w,u)*bb-dot(w,v)*ab)/det,second=(dot(w,v)*aa-dot(w,u)*ab)/det;return {1-first-second,first,second};}
struct Task{Tree& a;Tree& b;Work& work;std::vector<std::vector<Primitive>>& result;static int run(void* raw,uint64_t first,uint64_t last,char* error,uint64_t capacity)noexcept{auto& self=*static_cast<Task*>(raw);try{for(auto face=first;face<last;++face){const auto& triangle=self.a.triangle(face);for(const auto other:self.b.candidates(triangle)){auto primitive=intersect(triangle,self.b.triangle(other),self.work.q.tolerance,self.work);if(!primitive.count)continue;if(self.work.primitives.fetch_add(1)>=self.work.q.max_primitives)throw Failure(7,"Mesh intersection max_primitives exceeded.");primitive.first=face;primitive.second=other;self.result[face].push_back(primitive);}}return 0;}catch(const Failure& failure){message(error,capacity,failure.what());return failure.code;}catch(const std::exception& failure){message(error,capacity,failure.what());return 4;}catch(...){return 4;}}};
int compute(const penta_geometry_extra_host_v1* host,const penta_mesh_intersection_request_v1* request,penta_mesh_intersection_result_v1* target,char* error,uint64_t capacity)noexcept{try{require(host&&host->struct_size>=sizeof(*host)&&host->abi_version==PENTA_GEOMETRY_EXTRA_ABI_V1&&host->cancelled&&host->parallel_for&&request&&request->struct_size>=sizeof(*request)&&target&&target->struct_size>=sizeof(*target),"Incompatible mesh intersection ABI.");const auto& q=*request;auto& out=*target;for(const auto* mesh:{&q.first,&q.second})require(mesh->dimension==3&&mesh->vertices>=3&&mesh->vertices<=100000&&mesh->triangles>=1&&mesh->triangles<=200000&&mesh->points&&mesh->faces,"Mesh intersections require bounded real three-dimensional triangle embeddings.");require(q.first_width<=64&&q.second_width<=64&&(!q.first_width||q.first_values)&&(!q.second_width||q.second_values),"Intersection nodal fields retain1..64 coefficients per vertex.");require(q.max_primitives>=1&&q.max_primitives<=50000&&q.max_work>0&&q.max_work<=1000000000000ULL&&q.max_bytes<=1073741824&&q.tolerance>=0&&std::isfinite(q.tolerance)&&q.max_seconds>0&&q.max_seconds<=3600&&std::isfinite(q.max_seconds),"Invalid mesh intersection resource/tolerance bounds.");const auto maximumPoints=6*q.max_primitives;const uint64_t estimate=(q.first.triangles+q.second.triangles)*1800+q.max_primitives*2048+maximumPoints*(9+q.first_width+q.second_width)*8;require(estimate<=q.max_bytes&&out.primitive_capacity>=q.max_primitives&&out.point_capacity>=maximumPoints,"Mesh intersection memory/output capacity allowance exceeded.");require(out.coordinates&&out.first_barycentric&&out.second_barycentric&&out.offsets&&out.counts&&out.first_faces&&out.second_faces&&out.dimensions&&out.coplanar&&(!q.first_width||out.first_values)&&(!q.second_width||out.second_values),"Mesh intersection outputs are incomplete.");Work work{*host,q};for(const auto& field:{std::pair{q.first_values,q.first.vertices*q.first_width},std::pair{q.second_values,q.second.vertices*q.second_width}})for(uint64_t at=0;at<field.second;++at){if(at%1024==0)work.spend(1024);require(std::isfinite(field.first[at]),"Intersection nodal field coefficients must be finite.");}Tree a(work,q.first),b(work,q.second);std::vector<std::vector<Primitive>> results(q.first.triangles);Task task{a,b,work,results};char local[1024]{};const auto status=host->parallel_for(host->context,q.first.triangles,1500,Task::run,&task,local,sizeof(local));if(status)throw Failure(status,local[0]?local:"Parallel mesh intersection failed.");out.primitives=out.points=out.coplanar_pairs=0;for(const auto& list:results)for(const auto& primitive:list){work.spend(primitive.count*(12+q.first_width+q.second_width));const auto at=out.primitives++;out.offsets[at]=out.points+1;out.counts[at]=primitive.count;out.first_faces[at]=primitive.first+1;out.second_faces[at]=primitive.second+1;out.dimensions[at]=primitive.dimension;out.coplanar[at]=primitive.coplanar;out.coplanar_pairs+=primitive.coplanar;for(unsigned j=0;j<primitive.count;++j){const auto row=out.points++;const auto first=barycentric(a.triangle(primitive.first),primitive.points[j]),second=barycentric(b.triangle(primitive.second),primitive.points[j]);for(unsigned k=0;k<3;++k){out.coordinates[3*row+k]=finite(primitive.points[j][k]);out.first_barycentric[3*row+k]=finite(first[k]);out.second_barycentric[3*row+k]=finite(second[k]);}auto interpolate=[&](const Triangle& triangle,const auto& weights,const double* field,uint32_t width,double* values){for(unsigned c=0;c<width;++c){long double value=0;for(unsigned k=0;k<3;++k)value+=weights[k]*field[triangle.vertices[k]*width+c];values[row*width+c]=finite(value);}};interpolate(a.triangle(primitive.first),first,q.first_values,q.first_width,out.first_values);interpolate(b.triangle(primitive.second),second,q.second_values,q.second_width,out.second_values);}}out.work_units=work.used.load();if(host->charge&&host->charge(host->context,out.work_units,local,sizeof(local)))throw Failure(7,local[0]?local:"Mesh intersection host work allowance exceeded.");return 0;}catch(const Failure& failure){message(error,capacity,failure.what());return failure.code;}catch(const std::exception& failure){message(error,capacity,failure.what());return 4;}catch(...){return 4;}}
const penta_mesh_intersection_api_v1 api{sizeof(api),PENTA_MESH_INTERSECTION_ABI_V1,compute};
